const DECIMAL_INTEGER_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/;

export function parsePythonInt(value) {
  if (!DECIMAL_INTEGER_PATTERN.test(value)) {
    return null;
  }

  const isNegative = value.startsWith('-');
  const unsignedDigits = value.replace(/^[+-]/, '').replace(/_/g, '');
  const normalizedDigits = unsignedDigits.replace(/^0+(?=\d)/, '') || '0';
  const canonical = normalizedDigits === '0' ? '0' : `${isNegative ? '-' : ''}${normalizedDigits}`;

  return BigInt(canonical);
}

