const UNIT_MILLISECONDS = {
  seconds: 1000n,
  minutes: 60000n,
  hours: 3600000n,
  days: 86400000n,
  weeks: 604800000n,
};

function formatPythonValue(value) {
  if (typeof value === 'bigint') {
    return value.toString();
  }
  if (typeof value === 'string') {
